import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type QuestionBurstProps = Record<string, any>;

const QuestionMark: React.FC<{
  index: number;
  primaryColor: string;
  secondaryColor: string;
  accentColor: string;
  burstForce: number;
  durationInSeconds: number;
}> = ({ index, primaryColor, secondaryColor, accentColor, burstForce, durationInSeconds }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Pick a random color from the provided palette
  const colorRand = random(`color-${index}`);
  let color = primaryColor;
  if (colorRand > 0.33) color = secondaryColor;
  if (colorRand > 0.66) color = accentColor;
  
  // Randomly make some question marks outlines for visual variety
  const isOutline = random(`outline-${index}`) > 0.7;

  // --- Geometry & Positions ---
  
  // 1. Initial position (way off screen)
  const randAngleIn = random(`angle-in-${index}`) * Math.PI * 2;
  const distanceIn = Math.max(width, height) + 200;
  const startX = Math.cos(randAngleIn) * distanceIn;
  const startY = Math.sin(randAngleIn) * distanceIn;

  // 2. Central cluster hold position
  const clusterX = (random(`cluster-x-${index}`) - 0.5) * 40;
  const clusterY = (random(`cluster-y-${index}`) - 0.5) * 40;
  const clusterRot = (random(`cluster-rot-${index}`) - 0.5) * 60;

  // 3. Outward burst target position
  const randAngleBurst = random(`angle-burst-${index}`) * Math.PI * 2;
  const maxBurst = (Math.min(width, height) / 2) * (burstForce / 100);
  const burstDistance = (random(`burst-dist-${index}`) * 0.5 + 0.5) * maxBurst;
  
  const burstX = Math.cos(randAngleBurst) * burstDistance;
  const burstY = Math.sin(randAngleBurst) * burstDistance * 1.3; // Expand slightly more on Y axis for 9:16 verticality
  const burstRot = clusterRot + (random(`burst-rot-${index}`) - 0.5) * 180;

  // --- Timings ---
  const totalFrames = Math.round(durationInSeconds * fps);
  const enterDelay = random(`delay-${index}`) * (fps * 0.15); // Stagger entries up to 0.15s
  const burstDelay = Math.min(fps * 0.85, totalFrames * 0.3); // Burst occurs around 0.85s in
  const outDelay = totalFrames - fps + random(`out-delay-${index}`) * (fps * 0.2); // Animate out during the final second

  // --- Physics/Springs ---
  const enterProgress = spring({
    frame: frame - enterDelay,
    fps,
    config: { damping: 14, stiffness: 150, mass: 0.8 }
  });

  const burstProgress = spring({
    frame: frame - burstDelay,
    fps,
    config: { damping: 12, stiffness: 150, mass: 0.5 } // Light mass + stiff spring = energetic pop
  });

  const outProgress = spring({
    frame: frame - outDelay,
    fps,
    config: { damping: 20, stiffness: 100, mass: 1 } // Smooth non-bouncy exit
  });

  // --- Transformations ---
  
  // Continuous post-burst drift to keep momentum lively
  const activeDriftProgress = Math.max(0, frame - burstDelay);
  const driftX = Math.cos(randAngleBurst) * activeDriftProgress * (random(`dx-${index}`) * 1.5 + 0.5);
  const driftY = Math.sin(randAngleBurst) * activeDriftProgress * (random(`dy-${index}`) * 1.5 + 0.5);
  const continuousRot = activeDriftProgress * (random(`crot-${index}`) - 0.5) * 3;

  // Interpolate between the 3 main phases (Start -> Cluster -> Burst + Drift)
  const currentX = startX + (clusterX - startX) * enterProgress + (burstX - clusterX) * burstProgress + driftX;
  const currentY = startY + (clusterY - startY) * enterProgress + (burstY - clusterY) * burstProgress + driftY;
  const currentRot = clusterRot * enterProgress + (burstRot - clusterRot) * burstProgress + continuousRot;

  // Scale varying randomly from ~0.8 to ~1.6
  const baseScale = random(`scale-${index}`) * 0.8 + 0.8; 
  const clusterScale = baseScale * 0.6; // Shrink slightly while clustered
  const currentScale = clusterScale + (baseScale - clusterScale) * burstProgress;
  
  const finalScale = interpolate(outProgress, [0, 1], [currentScale, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  // Drop slightly while animating out
  const finalY = currentY + outProgress * 50;

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          transform: `translate(${currentX}px, ${finalY}px) scale(${finalScale}) rotate(${currentRot}deg)`,
          fontSize: 200, // Base large size
          fontWeight: 900,
          lineHeight: 1,
          color: isOutline ? "transparent" : color,
          WebkitTextStroke: isOutline ? `6px ${color}` : "none",
          filter: `drop-shadow(6px 6px 0px rgba(0,0,0,0.5))`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        ?
      </div>
    </AbsoluteFill>
  );
};

const QuestionBurst: React.FC<QuestionBurstProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 3,
  primaryColor = "#FF2A54",
  secondaryColor = "#00F0FF",
  accentColor = "#FFD700",
  questionCount = 35,
  burstForce = 120,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Outfit"]);
  {/* End Load Google Fonts */}

  // Prevent parser errors by pulling background logic into a variable
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Outfit" }}>
      {Array.from({ length: questionCount }).map((_, i) => (
        <QuestionMark
          key={i}
          index={i}
          primaryColor={primaryColor}
          secondaryColor={secondaryColor}
          accentColor={accentColor}
          burstForce={burstForce}
          durationInSeconds={durationInSeconds}
        />
      ))}
    </AbsoluteFill>
  );
};

export default QuestionBurst;